import{_t as e,it as t,n,rt as r}from"./chunks/framework.C6TizvAB.js";import"./chunks/assets.B25yjHWQ.js";var i=JSON.parse(`{"title":"APPLE","description":"苹果公司介绍","frontmatter":{"title":"APPLE","description":"苹果公司介绍","date":"2026-05-29T00:00:00.000Z","category":"置身事内","tags":["企业观察"],"order":2},"headers":[],"relativePath":"articles/zstn/firm/Apple.md","filePath":"articles/zstn/firm/Apple.md","articleMeta":{"updated":"2026-05-29","words":534,"minutes":1}}`),a={name:`articles/zstn/firm/Apple.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h2 id="截至2025年苹果的一些财务数据" tabindex="-1">截至2025年苹果的一些财务数据 <a class="header-anchor" href="#截至2025年苹果的一些财务数据" aria-label="Permalink to “截至2025年苹果的一些财务数据”">​</a></h2><p><img src="/images/IMG_1706.webp" alt="IMG_1706.webp" width="1080" height="1187"></p><p><img src="/images/IMG_1707260422.webp" alt="IMG_1707.webp" width="1080" height="1187"></p><p><img src="/images/IMG_1708.webp" alt="IMG_1708.webp" width="1080" height="1277"></p><p><img src="/images/IMG_1709.webp" alt="IMG_1709.webp" width="893" height="1103"></p><h2 id="苹果放弃造车的原因" tabindex="-1">苹果放弃造车的原因 <a class="header-anchor" href="#苹果放弃造车的原因" aria-label="Permalink to “苹果放弃造车的原因”">​</a></h2><p>苹果放弃汽车业务的原因众说纷纭，但有一点可以确定，即苹果无法在汽车产业复制自己对供应链强大的话语权。</p><p>在手机的供应链上，苹果不亲自研发生产零部件，而是用丰厚的订单指挥OEM企业。由苹果提出设计目标，技术送上马，设备扶一程，研发费用尽管开发票。苹果在库克治下成为了名副其实的半导体帝国。除了大名鼎鼎的A系列芯片，苹果用M踢开了英特尔，在久攻不下的基带芯片上成功摆脱了高通。</p><p>但是在新能源汽车领域，一方面，特斯拉已经先于苹果掌控了核心环节（芯片/算法），另一方面，宁德时代等供应商愿不愿意没事给自己找个爹。</p><h2 id="拓展阅读" tabindex="-1">拓展阅读 <a class="header-anchor" href="#拓展阅读" aria-label="Permalink to “拓展阅读”">​</a></h2><p><a href="https://mp.weixin.qq.com/s/1rGDAem6RWLzoDBcgtD1YA" target="_blank" rel="noreferrer">2026年4月22日-远川研究所-《告别库克时代，苹果的未来并不乐观》</a></p>`,11)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};